﻿/**
 * JavaScript 单文件视频书源（bookSourceType = 4）
 *
 * 站点形态：SSR + CSR 混合的短剧站，服务端渲染会把 loader 数据内联为
 * `_ROUTER_DATA = {...}`，详情/分类列表可直接从 SSR HTML 里取（无需浏览器渲染）。
 *
 * 链路：
 *   explore      -> /category/{slug}?page=N 的 _ROUTER_DATA.loaderData['category_$'].recommendList
 *   search       -> /api/search/result?aid=&query=&page=  （JSON API）
 *   getBookInfo  -> /detail?series_id= 的 _ROUTER_DATA.loaderData.detail_page.seriesDetail
 *   getChapters  -> 同上 seriesDetail.vid_list（每集一个 vid），章节 URL = /player/{series_id}/{vid}
 *   getContent   -> 校验播放页 vid 归属后回传播放页 URL，由宿主播放器 WebView 取流
 *   loginUi / loginAction -> 动态登录界面（V2 协议）：网页登录（扫码 / 手机号 + 短信验证码）
 *
 * 站点策略（真机实测）：播放页 SSR 不含流字段，取流由页面自身 JS 调站内受保护接口完成；
 * 游客可看前若干集，超配额集会被 302 回首集（带 `pc_locked_episode`），
 * 页面配置 `pc_watch_access.locked_episode_action = app`（站点引导改用 App）。
 */

var BASE = "https://hongguoduanju.com";
var AID = "8662";
// 单次页面/接口调用超时（ms）：站点 SSR 流式渲染偶发只回头不回 body，必须有界
var PAGE_TIMEOUT = 8000;
// 桌面 UA：PC 布局的登录入口（含扫码登录）只对桌面 UA 直出
var DESKTOP_UA = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36";

var config = {
    bookSourceUrl: BASE,
    bookSourceName: "红果短剧",
    bookSourceType: 4,
    bookSourceGroup: "视频",
    bookSourceComment: "[网站恢复]当前域名:hongguoduanju.com | 备用域名:同域 | 主管单位备案:京ICP备2021028909号-43 | 举报邮箱见官网页脚 " +
        "[技术]SSR _ROUTER_DATA 直取（零外置依赖、不经任何中转站）；播放页归属校验防「点任何集都播首集」；" +
        "游客额度内直连可播，超额度集需在源内完成网页登录。",
    loginUi: [],
    // 桌面 UA：站点的登录入口（含扫码登录）只在 PC 布局提供，移动布局是下载 App 的落地页
    header: "{\"User-Agent\":\"Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36\"}",
    exploreUrl: [
        { title: "真人剧", url: BASE + "/category/real-drama" },
        { title: "漫剧", url: BASE + "/category/comic-drama" },
        { title: "AI剧", url: BASE + "/category/ai-drama" },
        { title: "漫画", url: BASE + "/category/comic" }
    ],
    // 零外置依赖：本源已移除字节签名/CENC 取流链（实测该链在本网络被边缘节点拦截：
    // 签名请求返回空体、未签名 POST 连接被重置），故不再挂载 jsLib。
    lastUpdateTime: 0
};

/* ------------------------------------------------------------------ */
/* 基础设施                                                            */
/* ------------------------------------------------------------------ */

/** 从 HTML 中截取 `_ROUTER_DATA = {..}` 的完整 JSON 对象（字符串感知的括号配对） */
function extractRouterData(html) {
    if (!html) return null;
    var key = "_ROUTER_DATA = ";
    var i = html.indexOf(key);
    if (i < 0) return null;
    var start = i + key.length;
    var depth = 0, inStr = false, esc = false, end = -1;
    for (var k = start; k < html.length; k++) {
        var c = html.charAt(k);
        if (inStr) {
            if (esc) {
                esc = false;
            } else if (c === "\\") {
                esc = true;
            } else if (c === '"') {
                inStr = false;
            }
            continue;
        }
        if (c === '"') {
            inStr = true;
        } else if (c === "{") {
            depth++;
        } else if (c === "}") {
            depth--;
            if (depth === 0) {
                end = k + 1;
                break;
            }
        }
    }
    if (end < 0) return null;
    try {
        return JSON.parse(html.substring(start, end));
    } catch (e) {
        return null;
    }
}

/**
 * 统一文本化：java.ajax/java.post 返回的是 Java String，在 Rhino 里
 * `.length` 会被解析成 Java 的 `length()` 方法对象（不是 JS 的字符串长度），
 * 因此所有网络返回值必须先用 String() 收口成 JS 字符串再参与运算。
 */
function asText(v) {
    if (v === null || v === undefined) return "";
    return String(v);
}

/** 判断 java.ajax 返回的是不是异常堆栈（Legado 在 ajax 失败时返回 stackTraceStr） */
function isErrorText(txt) {
    var s = asText(txt);
    if (!s) return true;
    return s.indexOf("\tat ") >= 0 || s.indexOf("Exception:") >= 0;
}

/**
 * 站点页面统一请求选项。
 *
 * 必须显式 `Accept-Encoding: identity`：实测播放页在默认压缩协商下请求会挂死
 * （>30s 无响应），强制不压缩后同一页面 ~1s 返回（213KB，含 _ROUTER_DATA）。
 */
function siteAjaxOptions() {
    return ',{"headers":{"User-Agent":"' + DESKTOP_UA + '","Accept-Encoding":"identity"}}';
}

/**
 * 站点会下发字节系风控 Cookie（ttwid / __ac_nonce 等）。实测：本源 Cookie 里
 * 只要带着 `ttwid`，同一批动态接口（搜索/详情/播放页）就会长时间无响应；
 * 清掉后同一请求 ~0.1-0.5s 返回。
 *
 * C-1 铁律（2026-10-26 修复）：清理必须**按键删除**，禁止整域清除。
 * 原因（平台源码铁证）：整域清除（removeCookie 单参形式，见 CookieStore 实现）会连同
 * **WebView 域层**一起清除，而网页登录（内置浏览器）产生的凭据正是落在 WebView 域层
 * ⇒ 整域清一次就把刚拿到的登录态删掉了，表现为「网页登录成功但检测仍显示未登录」。
 * 现改用双参按键删除（只删源可读存储层的单个键，不触碰 WebView 域层）。
 */
var BOT_COOKIE_KEYS = { ttwid: 1, "ttwid_s": 1, "__ac_nonce": 1, "__ac_signature": 1, msToken: 1, s_v_web_id: 1 };

/** Cookie 串 -> 键名数组（只取分隔符左侧，绝不保留值） */
function cookieKeysOf(cookieStr) {
    var out = [];
    var s = asText(cookieStr);
    if (!s) return out;
    var parts = s.split(";");
    for (var i = 0; i < parts.length; i++) {
        var name = parts[i].split("=")[0].replace(/^\s+|\s+$/g, "");
        if (name && out.indexOf(name) < 0) out.push(name);
    }
    return out;
}

/** 当前源存储层里存在的风控键名 */
function presentBotKeys() {
    var out = [];
    var keys = cookieKeysOf((function () {
        try { return cookie.getCookie(BASE); } catch (e) { return ""; }
    })());
    for (var i = 0; i < keys.length; i++) {
        if (BOT_COOKIE_KEYS[keys[i]] === 1) out.push(keys[i]);
    }
    return out;
}

/** 按键清理风控 Cookie（无风控键时零副作用；不触碰 WebView 域层，登录态安全） */
function dropBotCookies() {
    var keys = presentBotKeys();
    if (!keys.length) return;
    var done = 0;
    for (var i = 0; i < keys.length; i++) {
        try {
            cookie.removeCookie(BASE, keys[i]);
            done++;
        } catch (e) {
            // 单键删除失败不阻断请求
        }
    }
    if (done) diagLog("[hg-source] dropped bot cookie count=" + done);
}

/**
 * C-3 闭环：把 WebView 域层的凭据并入源可读存储层。
 *
 * 网页登录在内置浏览器里完成，凭据先落在 WebView 域层；而 `java.ajax` 走的是
 * OkHttp + CookieStore（源可读存储层），两层不通 ⇒ 不并入就会出现
 * 「网页登录成功、但源请求仍按游客走」。
 */
function syncWebCookieToStore() {
    var web = "";
    try {
        web = asText(cookie.getWebCookie(BASE));
    } catch (e) {
        return { ok: false, reason: "读取 WebView 层失败：" + errorText(e) };
    }
    if (!web) return { ok: false, reason: "WebView 层暂无凭据（可能未打开网页登录或登录未完成）" };
    var before = cookieKeysOf((function () {
        try { return cookie.getCookie(BASE); } catch (e) { return ""; }
    })());
    try {
        // replaceCookie：合并语义，服务端下发的删除标记（空值）会被正确处理
        cookie.replaceCookie(BASE, web);
    } catch (e2) {
        return { ok: false, reason: "并入 WebView 凭据失败：" + errorText(e2) };
    }
    var after = cookieKeysOf((function () {
        try { return cookie.getCookie(BASE); } catch (e3) { return ""; }
    })());
    var added = [];
    for (var i = 0; i < after.length; i++) {
        if (before.indexOf(after[i]) < 0) added.push(after[i]);
    }
    diagLog("[hg-source] web cookie synced, webKeys=" + cookieKeysOf(web).length
        + ", addedKeys=" + added.length);
    return { ok: true, webKeys: cookieKeysOf(web).length, added: added };
}

/** GET 文本，带重试 */
function getText(url, times) {
    var n = times || 2;
    var last = "";
    var opt = siteAjaxOptions();
    for (var i = 0; i < n; i++) {
        dropBotCookies();
        // String() 收口：拼接结果在 Rhino 下可能是 ConsString，必须摊平成普通字符串
        // 第二参为单次调用超时（ms）：站点 SSR 流式渲染偶发挂起不发body，超时后重试
        last = asText(java.ajax(String(String(url) + opt), PAGE_TIMEOUT));
        if (!isErrorText(last) && last.length > 0) return last;
    }
    return last;
}

/** GET 纯 JSON 接口，带重试 */
function getJson(url, times) {
    var txt = getText(url, times);
    if (isErrorText(txt)) return null;
    try {
        return JSON.parse(txt);
    } catch (e) {
        return null;
    }
}

/** GET 服务端渲染页，取内联的 _ROUTER_DATA，带重试 */
function getRouterData(url, times) {
    var txt = getText(url, times);
    if (isErrorText(txt)) return null;
    return extractRouterData(txt);
}

/**
 * 读取本源持久化变量（`source.variable` 字符串，形如 `k=v;k2=v2`）。
 * 注：`source.get/put` 只进内存缓存，重启即丢；需要跨进程保留的开关放这里。
 */
function sourceVar(key) {
    var raw = "";
    try {
        raw = String(source.getVariable() || "");
    } catch (e) {
        return "";
    }
    if (!raw) return "";
    var parts = raw.split(/[;&\n]/);
    for (var i = 0; i < parts.length; i++) {
        var kv = parts[i].replace(/^\s+|\s+$/g, "");
        var eq = kv.indexOf("=");
        if (eq <= 0) continue;
        if (kv.substring(0, eq).replace(/^\s+|\s+$/g, "") === key) {
            return kv.substring(eq + 1).replace(/^\s+|\s+$/g, "");
        }
    }
    return "";
}

/**
 * 源内调试开关（E-5 / tasks 4.8.7）。
 *
 * 用途：把「播放方式选择」与「诊断输出」做成**源持久化变量**（`source.putVariable`），
 * 覆盖安装后仍保留；诊断输出**默认关闭**，避免污染正常使用时的 logcat。
 *
 * 键名与取值（都是源变量，与 `sourceVar`/`setSourceVar` 同一存储）：
 *   - `playmode`：`browser` = 内置浏览器播放；缺省/其它 = 播放器嗅探
 *   - `diag`：`1` = 打开诊断输出；缺省 = 关闭
 */
var DIAG_KEY = "diag";
var PLAYMODE_KEY = "playmode";

/** 诊断输出是否开启（默认关闭）。 */
function diagOn() {
    return sourceVar(DIAG_KEY) === "1";
}

/** 受开关控制的诊断日志：关闭时零输出（不产生 logcat 噪音）。 */
function diagLog(msg) {
    if (!diagOn()) return;
    try {
        java.log("[hg-diag] " + msg);
    } catch (e) {
        // 调试输出失败不影响主流程
    }
}

/** 写入本源持久化变量（保留其它键；value 为空即删除该键） */
function setSourceVar(key, value) {
    var raw = "";
    try {
        raw = String(source.getVariable() || "");
    } catch (e) {
        raw = "";
    }
    var out = [];
    var parts = raw ? raw.split(/[;&\n]/) : [];
    var found = false;
    for (var i = 0; i < parts.length; i++) {
        var kv = parts[i].replace(/^\s+|\s+$/g, "");
        if (!kv) continue;
        var eq = kv.indexOf("=");
        var k = eq > 0 ? kv.substring(0, eq).replace(/^\s+|\s+$/g, "") : kv;
        if (k === key) {
            found = true;
            if (value) out.push(key + "=" + value);
        } else {
            out.push(kv);
        }
    }
    if (!found && value) out.push(key + "=" + value);
    try {
        source.putVariable(out.join(";"));
    } catch (e2) {
        // 写入失败：调用方按默认行为继续
    }
}

/** 取 series_id（兼容 series_id= / 编码形式 / 仅剩数字尾段的场景） */
function seriesIdOf(url) {
    if (!url) return "";
    var s = String(url);
    var m = s.match(/series_id=(\d+)/);
    if (m) return m[1];
    m = s.match(/series_id%3D(\d+)/i);
    if (m) return m[1];
    m = s.match(/series_id[^0-9]{0,4}(\d{6,})/);
    if (m) return m[1];
    m = s.match(/(\d{15,})/);
    return m ? m[1] : "";
}

/** 取播放页 URL 末段的 vid */
function vidOf(url) {
    if (!url) return "";
    var parts = String(url).split("?")[0].split("/");
    return parts[parts.length - 1];
}

/** XML 文本转义（& 必须最先替换） */
function xmlEsc(s) {
    return String(s)
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;");
}

/** 详情页 SSR 数据 -> seriesDetail */
function fetchDetail(sid) {
    if (!sid) return null;
    var data = getRouterData(BASE + "/detail?series_id=" + sid, 2);
    if (!data || !data.loaderData) return null;
    var page = data.loaderData.detail_page;
    if (!page || !page.seriesDetail) return null;
    return page.seriesDetail;
}

/**
 * seriesDetail -> 搜索/发现条目。
 * 注意：详情/分类接口用 series_name，搜索接口用 series_title，两者取其一。
 */
function detailToBook(d) {
    if (!d || !d.series_id) return null;
    var title = d.series_name || d.series_title;
    if (!title) return null;
    var tags = d.tags || [];
    return {
        name: title,
        author: "红果短剧",
        bookUrl: BASE + "/detail?series_id=" + d.series_id,
        coverUrl: d.series_cover || "",
        intro: d.series_intro || "",
        kind: tags.join(" "),
        latestChapterTitle: d.episode_right_text || "",
        variable: ""
    };
}

/* ------------------------------------------------------------------ */
/* 登录（动态登录界面 V2）                                              */
/* ------------------------------------------------------------------ */

/**
 * 读取绑定对象上的字符串字段。
 * loginUi(state) / loginAction(action,state,form) 的 state、form 由宿主以 Java Map
 * 传入，Rhino 下不能假定 `obj.key` 一定有值，故 Map 取值与对象取值都要兜住。
 */
function pickStr(obj, key, def) {
    if (obj === null || obj === undefined) return def;
    if (typeof obj === "string") {
        try {
            obj = JSON.parse(obj);
        } catch (e) {
            return def;
        }
    }
    try {
        if (typeof obj.get === "function") {
            var v = obj.get(key);
            if (v !== null && v !== undefined) return String(v);
        }
    } catch (e1) {
        // 非 Map，继续按对象取值
    }
    try {
        var v2 = obj[key];
        if (v2 !== null && v2 !== undefined) return String(v2);
    } catch (e2) {
        // 忽略
    }
    return def;
}

/** 异常转用户可读文本 */
function errorText(e) {
    if (!e) return "未知错误";
    try {
        if (e.message) return String(e.message);
    } catch (x) {
        // 忽略
    }
    return String(e);
}

/**
 * 登录判据（**由源声明**）。
 *
 * C-2/3.4 约定：平台只提供「采集 + 对比 + 三态判定」能力，不硬编码任何站点字段；
 * 判据表达式与站点字段一律只出现在源里（这里）。未声明判据 ⇒ 结果只能是「无法判定」。
 */
var LOGIN_CRITERIA = {
    // 探测入口：分类页第一部剧的最后一集播放页
    courseUrl: BASE + "/category/real-drama",
    // 命中该标记 ⇒ 服务端按游客限流（未放行）
    lockedMarker: "pc_locked_episode",
    // 「本地已存在登录态」的键名清单（只比键名，值不参与判定）
    loginKeyMarks: [
        "sessionid", "sid_guard", "sid_tt", "uid_tt", "uid_tt_ss",
        "passport_csrf_token", "odin_tt", "sso_uid_tt", "sid_ucp_v1"
    ]
};

/**
 * 三层凭据键名体检（C-2）：源存储层 / WebView 域层 / 并集与来源标记。
 * 输出只含键名与来源，**绝不输出任何值**。
 */
function cookieDiagnosis() {
    var storeKeys = [];
    var webKeys = [];
    try { storeKeys = cookieKeysOf(cookie.getCookie(BASE)); } catch (e) { }
    try { webKeys = cookieKeysOf(cookie.getWebCookie(BASE)); } catch (e2) { }
    var origin = {};
    var i;
    for (i = 0; i < storeKeys.length; i++) origin[storeKeys[i]] = "store";
    for (i = 0; i < webKeys.length; i++) origin[webKeys[i]] = origin[webKeys[i]] ? "both" : "web";
    var union = [];
    for (var k in origin) union.push(k);
    var marked = [];
    for (i = 0; i < union.length; i++) {
        if (LOGIN_CRITERIA.loginKeyMarks.indexOf(union[i]) >= 0) marked.push(union[i]);
    }
    return { store: storeKeys, web: webKeys, union: union, origin: origin, marked: marked };
}

/**
 * 服务端放行探测（三态：已放行 / 未放行 / 无法判定）。
 * 铁律：请求未完成、数据缺失一律判「无法判定」，不得显示成「未登录」。
 * @return { state: "true"|"false"|"", msg: string, reason: string }
 */
function probeEntitlement() {
    var raw;
    try {
        // 先取分类页原文，**区分「请求未完成」与「数据缺失」**：
        // 两者都必须判「无法判定」，但原因不同（前者是网络/超时，后者是站点结构变更）。
        raw = getText(LOGIN_CRITERIA.courseUrl, 2);
    } catch (e) {
        return { state: "", msg: "无法判定：探测请求异常（" + errorText(e) + "）", reason: "request-error" };
    }
    if (isErrorText(raw) || !raw) {
        return { state: "", msg: "无法判定：分类页请求未完成（超时/空体），请稍后重试", reason: "request-error" };
    }
    var data = extractRouterData(raw);
    var c = data && data.loaderData ? data.loaderData["category_$"] : null;
    var list = c && c.recommendList ? c.recommendList : [];
    if (!list.length) {
        return { state: "", msg: "无法判定：分类页未返回数据（站点抖动或结构变更，非登录问题）", reason: "no-data" };
    }
    var sid = list[0].series_id;
    var vids = list[0].vid_list || [];
    if (!sid || !vids.length) {
        return { state: "", msg: "无法判定：剧集数据缺失（站点结构可能变更）", reason: "no-vid" };
    }
    var html = getText(BASE + "/player/" + sid + "/" + vids[vids.length - 1], 1);
    if (isErrorText(html) || !html) {
        return { state: "", msg: "无法判定：播放页请求未完成（超时/空体），请稍后重试", reason: "probe-timeout" };
    }
    if (html.indexOf(LOGIN_CRITERIA.lockedMarker) >= 0) {
        return { state: "false", msg: "未放行：服务端按游客限流（末集被拦截）", reason: "locked" };
    }
    return { state: "true", msg: "已放行：服务端未拦截末集", reason: "ok" };
}

/**
 * 取桌面布局 SSR 页面并注入「桌面平台特征 + 宽视口」。
 *
 * 站点服务端按 UA 直出 PC 版，但内置 WebView 是 Android 环境：水合阶段页面仍会按
 * navigator.platform / 触摸能力回落成移动版。因此把 SSR 的 PC HTML 取回后注入特征，
 * 再交内置浏览器渲染（登录页与「内置浏览器播放」共用）。
 *
 * @param url   目标页
 * @param rawHtml 可选：已取到的 HTML（避免重复请求）
 */
function buildDeskHtml(url, rawHtml) {
    var html = rawHtml ? String(rawHtml) : "";
    if (!html) {
        try {
            html = getText(url, 1);
        } catch (e) {
            html = "";
        }
    }
    if (!html || html.indexOf("<head") < 0) return "";
    // 站点自带的 width=device-width 视口会覆盖注入值（实测 innerWidth 仍为设备宽），先全部剔除
    html = html.replace(/<meta[^>]*name=["']viewport["'][^>]*>/gi, "");
    // 水合阶段页面还会按 navigator.platform 判定移动端，改成桌面值；
    // 触摸点数保持 1（不改 0）：字节安全 SDK 的滑块在 0 触摸点下会按鼠标事件监听，WebView 里拖不动
    var spoof = "<script>(function(){" +
        "try{Object.defineProperty(navigator,'platform',{get:function(){return 'Win32';}});}catch(e){}" +
        "try{Object.defineProperty(navigator,'maxTouchPoints',{get:function(){return 1;}});}catch(e){}" +
        "try{Object.defineProperty(navigator,'userAgentData',{get:function(){return undefined;}});}catch(e){}" +
        "})();</script>";
    var vp = "<meta name=\"viewport\" content=\"width=1280, initial-scale=0.42, maximum-scale=1.0, user-scalable=yes\">";
    return html.replace(/<head([^>]*)>/i, "<head$1>" + vp + spoof);
}

/** 登录页：取站点首页的 PC 版 HTML（含登录入口） */
function buildPcLoginHtml() {
    return buildDeskHtml(BASE + "/");
}

/**
 * 登录界面（V2）：宿主以 loginUi(state) 渲染 rows，state 是上一轮 loginAction 返回的对象。
 * 协议要点：text/password 必须带 key；button 必须带 action；label 只需 name。
 */
function loginUi(state) {
    var logged = pickStr(state, "loggedIn", "");
    var msg = pickStr(state, "msg", "尚未检测，请先打开网页登录");
    var status;
    if (logged === "true") {
        status = "已放行（服务端不再按游客限流）";
    } else if (logged === "false") {
        status = "未放行（服务端仍按游客限流）";
    } else {
        status = "无法判定（请求未完成或尚未检测）";
    }
    // 三层凭据键名体检（只列键名，不列值）
    var diagLine = "凭据键名：读取失败";
    try {
        var dg = cookieDiagnosis();
        diagLine = "凭据键名：存储层 " + dg.store.length + " 个 / WebView 层 " + dg.web.length
            + " 个 / 并集 " + dg.union.length + " 个；命中登录态键名："
            + (dg.marked.length ? dg.marked.join(",") : "无");
    } catch (eD) {
        // 体检失败不阻断界面
    }
    var modeName = "播放器嗅探（默认）";
    try {
        if (sourceVar(PLAYMODE_KEY) === "browser") {
            modeName = "内置浏览器（每集打开网页播放器）";
        }
    } catch (eM) {
        // 读变量失败按默认显示
    }
    var diagName = "关闭（默认）";
    try {
        if (diagOn()) diagName = "开启";
    } catch (eD2) {
        // 读变量失败按默认显示
    }
    return {
        rows: [
            { name: "账号状态：" + status, type: "label" },
            { name: msg, type: "label" },
            { name: diagLine, type: "label" },
            { name: "操作步骤：① 点“打开网页登录” → ② 网页右上角点“登录” → ③ 选“扫码登录”并截图 → ④ 用红果 App「我的 → ≡ → 扫一扫 → 选择图片」选中截图确认 → ⑤ 返回本页点“检测登录状态”。也可直接用手机号 + 短信验证码登录。", type: "label" },
            { name: "打开网页登录", type: "button", action: "webLogin" },
            { name: "同步网页登录凭据", type: "button", action: "syncWeb" },
            { name: "检测登录状态", type: "button", action: "check" },
            { name: "清除登录状态", type: "button", action: "logout" },
            { name: "播放方式：" + modeName, type: "label" },
            { name: "切换播放方式（嗅探 ⇄ 内置浏览器）", type: "button", action: "togglePlayMode" },
            { name: "诊断输出：" + diagName, type: "label" },
            { name: "切换诊断输出（排查问题时开启）", type: "button", action: "toggleDiag" },
            { name: "说明：站点播放器要「登录后」才放行，且取流走网页播放器（MSE）。建议：先完成上方登录，再把播放方式切到「内置浏览器」，点集后在内置网页里直接观看。", type: "label" },
            { name: "如果扫码/短信在阅读器内不可用（滑块拖不动、页面不刷新），用下面的 Cookie 方式：电脑浏览器打开站点登录 → F12 → Network → 任意本站请求 → Request Headers → 整段 Cookie 复制粘贴到这里。", type: "label" },
            { name: "Cookie", type: "text", key: "cookie", hint: "粘贴完整 Cookie 字符串（含 = 与分号）" },
            { name: "保存 Cookie 并检测", type: "button", action: "saveCookie" }
        ]
    };
}

/**
 * 登录动作：action 由按钮的 action 值触发，返回 {state|error|login|close}。
 * - state：重新渲染界面
 * - login：登录成功后保存到源（AES 加密）
 * - close：关闭弹窗
 */
function loginAction(action, state, form) {
    var act = String(action);
    if (act === "webLogin") {
        var html = buildPcLoginHtml();
        try {
            if (html) {
                // 用 PC HTML 打开内置浏览器：站点只在这个布局提供“登录 / 扫码登录”
                java.startBrowser(BASE, "登录站点", html);
            } else {
                // 取 PC HTML 失败时退化为直接打开站点首页
                java.startBrowser(BASE + "/", "登录站点");
            }
        } catch (e) {
            return { state: { loggedIn: "", msg: "打开登录页失败：" + errorText(e) } };
        }
        return { state: { loggedIn: "", msg: "已打开 PC 布局登录页。点右上角“登录”→ 选“扫码登录”并截图 → 红果 App「我的 → ≡ → 扫一扫 → 选择图片」确认；也可用手机号 + 短信验证码。完成后返回本页点“同步网页登录凭据”或“检测登录状态”。" } };
    }
    if (act === "saveCookie") {
        var ck = pickStr(form, "cookie", "").replace(/^\s+|\s+$/g, "");
        if (ck.indexOf("=") < 0) {
            return { state: { loggedIn: "", msg: "Cookie 为空或格式不对" }, error: { cookie: "请粘贴完整 Cookie" } };
        }
        try {
            cookie.setCookie(BASE, ck);
        } catch (e) {
            try {
                cookie.replaceCookie(BASE, ck);
            } catch (e2) {
                return { state: { loggedIn: "", msg: "保存 Cookie 失败：" + errorText(e2) }, error: { cookie: "保存失败" } };
            }
        }
        // 同步给内置浏览器，避免「源已登录但网页仍是游客」
        try { cookie.setWebCookie(BASE, ck); } catch (eW) { }
        var pc = probeEntitlement();
        if (pc.state === "true") {
            return {
                login: { loggedIn: "1", at: String(new Date().getTime()) },
                state: { loggedIn: "true", msg: "Cookie 已生效：" + pc.msg }
            };
        }
        return {
            state: { loggedIn: pc.state, msg: "Cookie 已保存，" + pc.msg },
            error: { cookie: "探测未通过" }
        };
    }
    // 同步网页登录凭据：内置浏览器（网页登录）产生的凭据在 WebView 域层，
    // 必须并入源存储层，java.ajax 才会真正带登录态（C-3 闭环）
    if (act === "syncWeb") {
        var sync = syncWebCookieToStore();
        var dp = probeEntitlement();
        var head = sync.ok
            ? ("已并入 WebView 层凭据（WebView 层键 " + sync.webKeys + " 个，新增 " + sync.added.length + " 个）；")
            : ("未并入：" + sync.reason + "；");
        if (dp.state === "true") {
            return {
                login: { loggedIn: "1", at: String(new Date().getTime()) },
                state: { loggedIn: "true", msg: head + dp.msg }
            };
        }
        return { state: { loggedIn: dp.state, msg: head + dp.msg } };
    }
    if (act === "check") {
        // 检测前先做一次凭据同步：网页登录结果可能只在 WebView 域层
        var sync2 = syncWebCookieToStore();
        var probe = probeEntitlement();
        var prefix = sync2.ok
            ? ("已同步 WebView 层凭据（新增 " + sync2.added.length + " 个键）；")
            : ("未同步 WebView 层凭据（" + sync2.reason + "）；");
        if (probe.state === "true") {
            return {
                login: { loggedIn: "1", at: String(new Date().getTime()) },
                state: { loggedIn: "true", msg: prefix + probe.msg }
            };
        }
        var tip = prefix + probe.msg;
        if (probe.state === "false") {
            var dg = cookieDiagnosis();
            if (dg.marked.length) {
                tip += "（本地已有登录态键名：" + dg.marked.join(",") + "，但服务端仍未放行，可能是账号权益问题）";
            }
        }
        return { state: { loggedIn: probe.state, msg: tip } };
    }
    if (act === "togglePlayMode") {
        var next = sourceVar(PLAYMODE_KEY) === "browser" ? "" : "browser";
        setSourceVar(PLAYMODE_KEY, next);
        return {
            state: {
                loggedIn: pickStr(state, "loggedIn", ""),
                msg: next === "browser"
                    ? "已切换为「内置浏览器播放」：点集后会打开网页播放器（站点播放器需浏览器环境才能出流）"
                    : "已切回「播放器嗅探」：由播放器内 WebView 尝试抓流"
            }
        };
    }
    if (act === "toggleDiag") {
        var on = diagOn();
        setSourceVar(DIAG_KEY, on ? "" : "1");
        return {
            state: {
                loggedIn: pickStr(state, "loggedIn", ""),
                msg: on
                    ? "已关闭诊断输出（默认状态，不产生额外日志）"
                    : "已开启诊断输出：排查问题时可在日志里看到 [hg-diag] 前缀的技术细节（不输出任何凭据值）"
            }
        };
    }
    if (act === "logout") {
        // 退出登录：此处**故意**整域清除（源存储层 + WebView 域层一起清），
        // 与请求前的按键清理形成对比 —— 只有「用户主动退出」才允许整域清。
        try {
            source.removeLoginInfo();
            cookie.removeCookie(BASE); // audit-allow: domain-clear
        } catch (e) {
            return { state: { loggedIn: "", msg: "清除失败：" + errorText(e) } };
        }
        return { state: { loggedIn: "false", msg: "已清除登录状态与 Cookie（含 WebView 域层）。" } };
    }
    return { state: { loggedIn: "", msg: "未知动作：" + act } };
}

