/** 发现页：/category/{slug}?page=N */
function explore(url, page) {
    var p = page || 1;
    if (!url) return [];
    // page=1 会 301 到规范 URL，首屏不带参数（少一次跳转）
    var u = p > 1 ? url + (url.indexOf("?") >= 0 ? "&" : "?") + "page=" + p : url;
    var data = getRouterData(u, 2);
    var books = [];
    if (!data || !data.loaderData) return books;
    var c = data.loaderData["category_$"];
    if (!c) return books;
    var list = c.recommendList || [];
    for (var i = 0; i < list.length; i++) {
        var b = detailToBook(list[i]);
        if (b) books.push(b);
    }
    return books;
}

/** 搜索：站内 JSON 接口 */
function search(key, page) {
    var p = page || 1;
    var books = [];
    if (!key) return books;
    var u = BASE + "/api/search/result?aid=" + AID
        + "&query=" + encodeURIComponent(key) + "&page=" + p;
    var data = getJson(u, 2);
    if (!data || !data.searchList) return books;
    var list = data.searchList;
    for (var i = 0; i < list.length; i++) {
        var item = list[i];
        // doc_type 23 = 短剧条目，其余（演员等）跳过
        if (item.doc_type !== 23) continue;
        var b = detailToBook(item.video_data);
        if (!b && item.name) {
            b = {
                name: item.name,
                author: "红果短剧",
                bookUrl: BASE + "/detail?series_id=" + (item.keyword || ""),
                coverUrl: "",
                intro: "",
                kind: "",
                latestChapterTitle: "",
                variable: ""
            };
        }
        if (b) books.push(b);
    }
    return books;
}

/** 详情：只补搜索阶段拿不到的字段 */
function getBookInfo(book) {
    var sid = seriesIdOf(book && book.bookUrl);
    var d = fetchDetail(sid);
    if (!d) {
        return { tocUrl: book.bookUrl };
    }
    var tags = d.tags || [];
    return {
        name: d.series_name || d.series_title || book.name,
        author: "红果短剧",
        intro: d.series_intro || "",
        coverUrl: d.series_cover || "",
        kind: tags.join(" "),
        latestChapterTitle: d.episode_right_text || "",
        tocUrl: book.bookUrl
    };
}

/** 目录：网页 SSR 的 detail 内联数据（seriesDetail.vid_list 即每集 vid） */
function getChapters(book) {
    var sid = seriesIdOf(book && (book.bookUrl || book.tocUrl));
    var chapters = [];
    var rawBookUrl = String((book && book.bookUrl) || "");
    diagLog("[hg-source] toc sidLen=" + String(sid).length
        + " bookUrlLen=" + rawBookUrl.length
        + " hasSidKey=" + (rawBookUrl.indexOf("series_id=") >= 0)
        + " hasQuery=" + (rawBookUrl.indexOf("?") >= 0));
    var d = fetchDetail(sid);
    if (!d) return chapters;
    var vids = d.vid_list || [];
    for (var i = 0; i < vids.length; i++) {
        chapters.push({
            title: "第" + (i + 1) + "集",
            url: BASE + "/player/" + sid + "/" + vids[i]
        });
    }
    return chapters;
}

/**
 * 播放：把播放页交给宿主播放器，由 WebView 嗅探取流。
 *
 * 站点策略（真机实测）：
 *   - 游客可看前若干集（页面内联 `seriesDetail.accessible_episode_cnt`
 *     与 `libraConfig.visible_episode_cnt`，实测本剧为 50/86）；
 *   - 超出配额的集会被 302 回首集并附 `pc_locked_episode`，
 *     页面配置 `pc_watch_access.locked_episode_action = app`（站点引导去 App 看）；
 *   - 播放页 SSR 不含任何流字段（m3u8/mp4/video_model/spade 计数均为 0），
 *     取流由页面自身 JS 调站内受保护接口完成 ⇒ 只能交给 WebView 执行。
 *
 * 2026-10-25 修复：越权集播放页会 302 回首集，宿主跟随重定向 ⇒ 点任何集都播首集；
 * 因此回传播放页 URL 前必须比对页面内 vid 归属，归属不符一律拒绝并给出明确提示。
 */
function getContent(chapter, book, nextChapterUrl) {
    var url = String((chapter && chapter.url) || "");
    var vid = vidOf(url);
    if (!vid) return "";

    var st = pagePlaybackState(url, vid);
    if (!st.belongs) {
        // 区分「站点把本集锁回」与「页面本身没取回来」，避免把网络问题误报成配额问题
        if (st.authState === "no-data" || st.authState === "no-page") {
            diagLog("[hg-source] page fetch failed, state=" + st.authState + ", vidLen=" + vid.length);
            throw new Error("播放页取回失败（站点响应超时或为空），请稍后重试。");
        }
        diagLog("[hg-source] locked episode, refuse"
            + ", vidLen=" + vid.length
            + ", state=" + st.authState
            + ", visible=" + st.visibleCnt);
        throw new Error("本集超出游客免费范围（本剧可免费 " + st.visibleHint
            + "）：站点限制需 App 观看。可在书源登录页完成网页登录后再试。");
    }
    diagLog("[hg-source] play page ok, state=" + st.authState
        + ", visible=" + st.visibleCnt + ", vidLen=" + vid.length);

    // 可选：内置浏览器播放（源变量 playmode=browser）
    // 站点播放器靠页面 JS 生成风控签名才能在 MSE 里出流，只有真实浏览器环境可用；
    // 该模式下把「桌面版播放页」交内置浏览器渲染，播放器内不再尝试嗅探。
    if (sourceVar("playmode") === "browser") {
        // 复用上面已取的播放页 HTML，避免第二次请求（站点对重复请求会明显变慢）
        var html = buildDeskHtml(url, st.html);
        if (!html) {
            throw new Error("打开网页播放器失败：播放页取回为空，请稍后重试或切回「播放器嗅探」模式。");
        }
        var idx = parseInt(String((chapter && chapter.index) || "0"), 10) + 1;
        var title = "第" + idx + "集";
        try {
            java.startBrowser(url, title, html);
            diagLog("[hg-source] browser mode, htmlLen=" + html.length);
        } catch (eB) {
            diagLog("[hg-source] startBrowser failed: " + errorText(eB));
        }
        return "";
    }
    return url;
}


/**
 * 播放页归属与登录态。
 *
 * 站点对越权集会把 `/player/{sid}/{vid}` 302 回首集；java.ajax 自动跟随重定向，
 * 因此必须比对页面内 `vid`，否则宿主会把首集流当成当前集播放。
 *
 * 页面偶发返回空体（实测），故取页重试 2 次，减少误判成「越权」。
 * 返回值带上原始 HTML，供「内置浏览器播放」复用，避免重复请求。
 */
function pagePlaybackState(url, vid) {
    var raw = getText(url, 2);
    var data = isErrorText(raw) ? null : extractRouterData(raw);
    if (!data || !data.loaderData) return { belongs: false, authed: false, authState: "no-data", visibleCnt: "", visibleHint: "?", html: raw };
    var page = data.loaderData["player_(series_id)/(vid)/page"];
    if (!page || !page.vid) return { belongs: false, authed: false, authState: "no-page", visibleCnt: "", visibleHint: "?" };
    var req = page.req || {};
    var libra = req.libraConfig || {};
    // visible_episode_cnt 形如 {val: 50}；缺失时留空
    var vis = libra.visible_episode_cnt;
    var visible = (vis && vis.val !== undefined) ? String(vis.val) : "";
    // 提示里用「N/总数」的直观形式（总数取 seriesDetail.episode_cnt）
    var detail = page.seriesDetail || {};
    var total = detail.episode_cnt ? String(detail.episode_cnt) : "";
    var hint = visible ? (visible + (total ? "/" + total + " 集" : " 集")) : "部分集数";
    return {
        belongs: String(page.vid) === String(vid),
        authed: req.pcAuthenticatedPlayback === true
            || String(req.pcPlaybackAuthState || "") === "authenticated",
        authState: String(req.pcPlaybackAuthState || "unknown"),
        visibleCnt: visible,
        visibleHint: hint,
        html: raw
    };
}
